    "passage": "Sleepwalking is a strange thing.  When people sleepwalk, their bodies are moving, but their brains are still sleeping.  In the past, there were many interesting stories.   ___(1)___  He saw it on the table the next day and it was so strange to him!  Another girl was painting a beautiful picture on her wall at 2:00 a.m.\nHowever, sleepwalking can also be a big problem.   ___(2)___  This is not safe because they cannot see things well.  They might fall down.\nSometimes a sleepwalker may do something wrong.  For example, if a man hits someone while he is sleepwalking, is it his fault?  In many places, if the person did not know what he was doing, he may not get a big punishment.  But doctors say we still need to be careful.   ___(3)___  and put away sharp things.  These things can help these people keep safe.",
