    "passage": "Do you have a broom in your house?  In some countries, people like a new broom because it can bring things to them.  However, you should not take your old broom to a new house.   ___(1)___  They believe an old broom carries all the “bad things” from the old place.  Last month, while my aunt was moving into her new house, she bought a new broom.  She wanted to start a new life there.\nIn the UK, there is another special superstition about luck.  On the first day of a new month, some people say “White Rabbit” three times after they wake up.   ___(2)___  They believe this can bring them a very lucky month.  Last Sunday was the first day of February.  My brother said the words loudly before he brushed his teeth!\n ___(3)___  They are not real, but they make life more fun.  When we travel to other countries, we can learn these stories from our friends.  We should respect these habits because this shows our love for different people.",
