    "passage": "Last night, I had a very special dream.  In the dream, when I was walking in a park, I saw a blue tiger.  It was flying in the sky!  At that time,  ___(1)___ .  People call this a “lucid dream.”  A lucid dream is a special dream, and you know you are dreaming when you are in a lucid dream.\nIn my dream, everything felt real.  I was standing on a cloud, and many birds were singing around me.  Then, I wanted to change the dream.  I thought about a big cake, and it came out!   ___(2)___  It was so much fun because I could do many things and they are hard to do in real life.\nHowever, I woke up fast.   ___(3)___  She told me it was time to eat breakfast.  I was a little sad because I was having a great time in my world.  Now, I want to practice having lucid dreams every night.  It is a lot of fun!",
