    "groupId": "U3-CLOZE-19",
    "passage": "After Katarina moved to a new city, she had bad dreams almost every night.  These dreams always woke her up.  She couldn’t get enough sleep and was tired all the time.\nOne night, Katarina woke up from a terrible dream again.  She looked at the clock.  It was 1:15 a.m.  At  ___(1)___ , she felt thirsty and walked into the kitchen.  When she walked into the kitchen, she saw her brother, Nikolay.  He was wiping the dining table in the dark!  “Nikolay, what are you doing?”  Katarina asked.  Nikolay didn’t answer.  His eyes weren’t open!  Katarina didn’t wake him up.  She just took her cup to get some water.   ___(2)___ !  Katarina was scared.  She dropped the cup, and it broke in half.\nThe sound finally woke Nikolay up.  “What happened?  Why am I in the kitchen?” asked Nikolay.  He didn’t remember that at all.  Katarina said, “Your eyes weren’t open just now.   ___(3)___   And I dropped my cup because of the earthquake.”  “Take it easy.  Are you OK?  You look very tired,” Nikolay said.  Katarina told him about her problem.  Nikolay went back to his room and gave her a dreamcatcher.  “Hang this by your bed.  The web catches the bad dreams,   ___(4)___ ,” he told her.  Katarina hung it up, and finally, she could sleep through the night.",
