    "passage": "Nadia: You look very tired today, Vlad.  What happened?\nVlad: I had a terrible dream last night, and I couldn’t fall asleep again.\nNadia: Poor you.  What time did you wake up from the dream?\nVlad: At about  ___(1)___ .\nNadia: 3:45 a.m.?  That was in the middle of the night!  What was your dream about?\nVlad: Well, in my dream, I  ___(2)___  the clothes in the yard.  Suddenly, a big black dog ran after me.  I was very scared, so I ran back into the house.\nNadia: And then?\nVlad: Then I saw my brother, Peter.  He was mopping the stairs.  I cried for help, but he just looked at me and said nothing.  I  ___(3)___  when the dog jumped on me!  Then I woke up.\nNadia: That sounds terrible.  Maybe you are just nervous about your math test the next day.\nVlad: Maybe.  I am really worried about it.\nNadia:  ___(4)___   You studied hard for days.  You will be fine.  Oh, maybe you can hang a dreamcatcher by your bed.  The web catches bad dreams, but the good ones go through the holes.\nVlad: Thanks for the tip.  I’ll try it tonight.  Time to go to bed early!",
