    "passage": "（Ryan’s classmates are thanking him.）\nMarco: Why are your classmates so happy?\nRyan: Today is my birthday.  I made a cake for everyone in my class.\nMarco: Made a cake?  Could you?\nRyan: Yes, I planned  ___(1)___  a cake for my classmates, and my dad gave me a hand.  He is a good cook in my family, and he loves cooking very much.\nMarco: How about you?  Do you love cooking, too?\nRyan: Yes, I started  ___(2)___  a cake last year.  At first, I only made terrible cakes.  Dad told me, “Just keep  ___(3)___  on it.  You can make a yummy cake one day.”  So I often practice it.\nMarco: Do you want to be a good cook like your dad?\nRyan: Of course, but I’m not good enough.  I still need  ___(4)___ .\nMarco: You work very hard.  I’m sure you can be good at cooking in the future.\nRyan: Thanks, Marco.",
