    "passage": "(In the classroom after school.)\nLuke: Are you going to the music club today?\nSarah:  ___(1)___   There is a lot of work I need to do.\nLuke: Oh, that’s too bad.  We’re planning a show for next month.\nSarah: Really?  That sounds fun.\nLuke: We need someone to sing.  You’re good at singing!\nSarah: Thanks.  But I don’t like singing in front of people.  I always get butterflies in my stomach.\nLuke:  ___(2)___   You can just practice with us first.\nSarah: Hmm... maybe.  I’ll think about it.\nLuke: Great!  We’re meeting again this Friday.\nSarah:  ___(3)___   Maybe I’ll sing a little, too.",
