    "passage": "Last night, when I was watching the news, I saw a special report about “Robot Workers in 2050.”  Many things are different.  In the report, people did all the hard work in factories in the past.  However, now robots are doing most of the jobs.\n ___(1)___   For example, they can work 24 hours a day without getting tired.  They don’t need to eat or sleep, and they never get sick.  Because of this, things are becoming very cheap for everyone.\nBut not everyone is happy.   ___(2)___   Many people lost their jobs because robots can do their work well.  Mr. Chen used to be a worker.  But a robot took his job last month.  He felt very sad and didn’t know what to do next.\n ___(3)___   We can learn to work with robots.  For example, robots can do the dangerous work, and we can do the creative work, like painting or writing stories.  If we use robots in the right way, our life can be very different from now.",
