    "type": "cloze",
    "groupId": "U4-CLOZE-33",
    "passage": "The world is changing.  In the past, many people worked in factories.  However, many robots are doing that work now.  Last night, when I was watching a video about future jobs, I learned some important things.   ___(1)___ \nFirst, machines are good at some jobs, but they do not have feelings.  We should be creative.  For example, we should spend more time on art, music, or talking to people.  These things show our ideas and feelings.\nSecond, learning never stops.   ___(2)___   My father was a driver ten years ago.  Now, he is learning how to use a computer.  He always studies for one hour after he finishes his work.  He knows he has to catch up with the world.\nWhat can we do to prepare for the future?   ___(3)___   We should be kind to others and always be ready to learn new skills.  In this way, we can have a good life when the world changes.",
    "subNum": 1,
    "totalSubs": 3,
    "question": "請選出克漏字空格 ___(1)___ 最適當的答案：",
