    "passage": "Rene liked dogs and cats when he was a little boy.   ___(1)___   He often reads books about animals and looks for information on the Internet.\nHowever, taking good care of pets is not an easy job.  At first, he didn’t know how to do it well.  For example, he saw one important thing:  ___(2)___ .  Some dogs even got sick easily.  He became very worried and tired.\nSometimes he wanted to stop doing this.  But his family always told him, “Successful people never stop trying.”  So, he told himself that  ___(3)___ .  He started asking animal doctors for help and learned a lot from them.\nAfter years of hard work, he is now a great animal doctor.  He often makes YouTube videos to tell people his ideas about keeping pets.  At the end of his videos, he always says, “ ___(4)___   Just do your best!”",
