    "passage": "My name is Toby, and I am a foley artist.  How do people in movies make walking sounds?  That’s my job!  I make sounds for movies.   ___(1)___  at the right time is a great art.\nEvery day, I need to watch movies many times.  I want to find every small part.  Then, I start my work.  I practice hitting different things to make “fighting” sounds.   ___(2)___   For example, I use some vegetables to make the sound of breaking bones!\nDuring my work, I keep  ___(3)___  different ways to make the sounds perfect.  I want to help people feel like they are inside the movie.  It is a long work, but I usually finish making one part of the movie in a few hours.   ___(4)___ , but it is never boring.  I love my job because I can tell stories with sounds.",
