    "type": "mcq",
    "question": "A：What _____ you _____ when I _____ home five minutes ago? B：Some fish and noodles.",
    "options": {
      "A": "did; cook; getting",
      "B": "were; cooking; getting",
      "C": "were; cooking; got",
      "D": "did; cook; got"
    },
    "answer": "C",
    "explanation": "詳解：由時間副詞 five minutes ago 可知時間發生在過去。連接詞 When 句型，通常用過去簡單式表示進行時間較短的動作，而進行時間較長的動作則以過去進行式表示。此句中，got home 是一個瞬間的動作，故選 (C)。",
