    "question": "Doctors always tell us _____ more fruit and vegetables（蔬菜）, but it is not easy _____ a person’s eating habits.",
    "options": {
      "A": "to eat; changed",
      "B": "eating; to change",
      "C": "to eat; to change",
      "D": "eating; changing"
    },
    "answer": "C",
    "explanation": "詳解：「叫某人做某動作」的句型為「tell sb to V」，而虛主詞 it 開頭的句型，後面的真主詞常以不定詞的形式呈現。",
