    "options": {
      "A": "Ride; is",
      "B": "To ride; be",
      "C": "Riding; is",
      "D": "Ride; to be"
    },
    "answer": "C",
    "explanation": "詳解：若將 when it is cool 移置句首，即可知此其實為「動名詞／不定詞…＋be 動詞...」的句型，故第一格用 Riding，第二格用 is。",
