    "category": "文法選擇",
    "type": "mcq",
    "question": "James is planning _____ the baseball school team although（雖然）it is difficult _____ him to play baseball.",
    "options": {
      "A": "to join; to",
      "B": "join; for",
      "C": "to join; for",
      "D": "joins; about"
    },
    "answer": "C",
    "explanation": "詳解：表達「計畫做……」用 plan to V；表達「對……來說」用「for＋人（受格）」。",
