    "type": "mcq",
    "question": "It _____ fun for James and his brothers _____ soccer when they were little. They often played for three hours after school.",
    "options": {
      "A": "is; to play",
      "B": "are; plays",
      "C": "was; to play",
      "D": "be; playing"
    },
    "answer": "C",
    "explanation": "詳解：虛主詞 it 開頭的句型，後面的真主詞常以不定詞的形式呈現，且 be 動詞應視所發生的時間來決定用什麼時態。由子句 when they were little 可知 be 動詞要用過去式 was。",
