    "unitLabel": "康軒英語 02 (L4)",
    "category": "文法選擇",
    "type": "mcq",
    "question": "Hi, Heidi! I’m happy _____ you here. I have a lot of work _____ . Can you help me with it?",
    "options": {
      "A": "to see; do",
      "B": "see; doing",
      "C": "seeing; to do",
      "D": "to see; to do"
    },
    "answer": "D",
    "explanation": "詳解：第一個空格，不定詞可放在形容詞後面，表達主詞的狀況；第二個空格，用不定詞來修飾前面的 work，表「很多工作要做」。",
