    "passage": "Dear Grant and Rebecca,\n\nWe want  ___(1)___  you for asking us to have dinner with you last night.  Rebecca,  ___(2)___ .  We loved all your food.  Everything was delicious, especially the steak and the clam chowder.  They must be your specialties.  We’re thinking about  ___(3)___  to cook these two dishes from you.\n\nWe also enjoyed talking with you.  You told us about your interesting trip to Orchid Island（蘭嶼）,  ___(4)___ .  Peter and I both enjoy water sports.  When we go back, we will tell you about our trip, too.\n\nLove,\nErica and Peter\n especially 尤其  steak 牛排  clam chowder 蛤蜊巧達湯  specialty 拿手菜  dish 菜肴  trip 旅行  will 將",
